    completed = true;
  });
  await tester.flushMicrotasks(1);
  return (completed);
}, () => (true));

await $test.run("flushMacrotasks drains pending setTimeout macrotasks", async () => {
  const sleep = $test.sleep;
  const tester = createAsyncTester();
  let step = 0;
  setTimeout(() => {
    step = 42;
  }, 0);
  await tester.flushMacrotasks(1);
  return (step);
}, () => (42));

