function createTestEach(registerTest) {
  function formatTitle(title, row, isObject) {
    if (isObject) {
      return title.replace(/\$([a-zA-Z0-9_]+)/g, (_, key) => {
        const v = row[key];
        return typeof v === 'object' && v !== null ? JSON.stringify(v) : String(v);
